import subprocess, re, os, json
# Step 1: gather tasklet callback function names via tasklet_setup(fn and .func = / .function =
files = subprocess.run(["grep","-rn","--include=*.c","-e","tasklet_setup(","-e",".function =","-e","DECLARE_TASKLET(","-e","DECLARE_TASKLET_OLD(","-e","tasklet_init(","drivers","net"],capture_output=True,text=True).stdout
cb={}
for line in files.splitlines():
    m=re.search(r'(\S+):\d+:\s*tasklet_setup\(\s*&?([\w\>\.\-]+)\s*,\s*(\w+)\s*\)',line)
    if m: cb.setdefault(m.group(3),[]).append((m.group(1),line.split(':')[1]))
    m=re.search(r'(\S+):(\d+):\s*DECLARE_TASKLET(?:_OLD)?\(\s*(\w+)\s*,\s*(\w+)\s*\)',line)
    if m: cb.setdefault(m.group(4),[]).append((m.group(1),m.group(2)))
    m=re.search(r'(\S+):(\d+):\s*tasklet_init\([^;]*?,\s*(\w+)\s*,',line)
    if m: cb.setdefault(m.group(3),[]).append((m.group(1),m.group(2)))
print(len(cb),"tasklet callbacks")
out={}
for fn,locs in cb.items():
    src=locs[0][0]
    # find function body
    body=[]
    try:
        txt=open(src).read().splitlines()
    except: continue
    for i,l in enumerate(txt):
        if re.match(r'^\s*(?:static\s+)?(?:void\s+\w+\s*\()\w*%s\w*'%re.escape(fn), l) or re.search(r'\b%s\s*\('%re.escape(fn), l):
            pass
    # simpler: locate "fn(...)" definition
    start=None
    for i,l in enumerate(txt):
        if re.search(r'\b%s\s*\([^;]*\)\s*$'%re.escape(fn),l) or re.search(r'\b%s\s*\('%re.escape(fn),l) and not re.search(r'(->|\.|\w)\s*%s'%re.escape(fn),l):
            start=i; break
    if start is None: continue
    depth=0; seen=False; end=min(start+200,len(txt))
    for j in range(start,end):
        l=txt[j]
        depth+=l.count('{')-l.count('}')
        if '{' in l: seen=True
        if re.search(r'\bspin_lock\s*\(',l):
            out.setdefault(src,[]).append((fn,start+1,j+1,l.strip()))
        if seen and depth<=0 and j>start:
            break
res={k:v for k,v in out.items()}
for k,v in sorted(res.items()):
    print(k)
    for fn,ds,ls,line in v:
        print("   ",fn,ds,ls,line[:100])
json.dump(res,open(os.environ.get("TMPDIR","/tmp")+"/tasklet_plain.json","w"),indent=1)
EOF

