import re, os, json, collections
tmp=os.environ.get("TMPDIR","/tmp")
data={}
for name,f in [("tasklet","tasklet_plain.json"),("napi","napi_plain.json")]:
    data[name]=json.load(open(os.path.join(tmp,f)))
# for each (file, lockname) enumerate all lock sites of that name in that file
def sites(file,lockname):
    txt=open(file).read().splitlines()
    res=[]
    pat=re.compile(r'(spin_(?:un)?lock(?:_bh|_irqsave|_irq|_irqrestore)?(?:_nested)?(?:_nosave)?|read_lock|write_lock|spin_trylock\w*)\s*\(\s*&?%s\s*'%re.escape(lockname))
    for i,l in enumerate(txt):
        m=pat.search(l)
        if m:
            res.append((i+1,m.group(1),l.strip()[:90]))
    return res
report={}
for typ,per_file in data.items():
    for file,items in per_file.items():
        for fn,ds,ls,line in items:
            lockname=re.search(r'spin_lock\(&?([^)]+)\)',line).group(1).rstrip(')')
            s=sites(file,lockname)
            kinds=collections.Counter(k for _,k,_ in s)
            # classify: does any site use plain spin_lock/unlock?
            report.setdefault(file,[]).append((fn,lockname,ls,dict(kinds),s))
for file,entries in sorted(report.items()):
    print("=====",file)
    for fn,lockname,ls,kinds,s in entries:
        print(f"  fn={fn} lock={lockname} line={ls} kinds={kinds}")
        for ln,k,l in s:
            print(f"     {ln:5d} {k:22s} {l}")
EOF

